using Beep.OilandGas.Models.Data.Production;
using Beep.OilandGas.Models.Data.Company;
using Beep.OilandGas.Client.App;
using Beep.OilandGas.Models.Data;
using Beep.OilandGas.Web.Services;
using Xunit;
namespace Beep.OilandGas.Web.Auth.Tests;
public sealed class WellTestReviewStateTests
{
    private static CompanyClientContext Company(){var c=new CompanyClientContext();Assert.True(c.TrySelect(c.Clear(),"actor",new(new("tenant","A"),[],[])));return c;}
    private static WellTestReview Review(IReadOnlyList<WellTestResponse> rows)=>new(new("tenant","A"),"actor","field","well",DateTimeOffset.UtcNow,rows);
    private static WellTestResponse Row()=>new(){TestId="test/1",Uwi="well",WellId="internal-id",OilFlowAmount=null,GasFlowAmount=0};
    [Fact] public async Task RecordedIdentityAliasesAndMissingValuesArePreserved(){using var c=Company();using var s=new WellTestReviewState(c);await s.LoadAsync("well",()=>Task.FromResult<string?>("field"),_=>Task.FromResult(Review(new List<WellTestResponse>{Row()})));Assert.True(s.Confirmed);Assert.Equal("field",s.Field);Assert.NotNull(s.RetrievedAtUtc);Assert.Equal("well",s.Well);Assert.Null(Assert.Single(s.Rows).OilFlowAmount);Assert.Equal(0,s.Rows[0].GasFlowAmount);}
    [Theory][InlineData("identity")][InlineData("well")][InlineData("duplicate")][InlineData("null")]
    public async Task InvalidSourceCannotPublish(string fault){using var c=Company();using var s=new WellTestReviewState(c);var row=Row();List<WellTestResponse> rows=[row];switch(fault){case "identity":row.TestId="";break;case "well":row.Uwi="other";row.WellId="other-id";break;case "duplicate":rows.Add(row);break;default:rows=null!;break;}await Assert.ThrowsAsync<InvalidOperationException>(()=>s.LoadAsync("well",()=>Task.FromResult<string?>("field"),_=>Task.FromResult(Review(rows))));Assert.False(s.Confirmed);Assert.Empty(s.Rows);}
    [Fact] public async Task ActualEmptyHistoryDiffersFromFailedReload(){using var c=Company();using var s=new WellTestReviewState(c);await s.LoadAsync("well",()=>Task.FromResult<string?>("field"),_=>Task.FromResult(Review(new List<WellTestResponse>())));Assert.True(s.Confirmed);await Assert.ThrowsAsync<HttpRequestException>(()=>s.LoadAsync("well",()=>Task.FromResult<string?>("field"),_=>throw new HttpRequestException()));Assert.False(s.Confirmed);Assert.Empty(s.Rows);Assert.Null(s.Well);}
    [Fact] public async Task CompanyChangeClearsDisplayedSourceAndRejectsLateResponse(){using var c=Company();using var s=new WellTestReviewState(c);await s.LoadAsync("well",()=>Task.FromResult<string?>("field"),_=>Task.FromResult(Review(new List<WellTestResponse>{Row()})));var pending=new TaskCompletionSource<WellTestReview>();var load=s.LoadAsync("well",()=>Task.FromResult<string?>("field"),_=>pending.Task);c.Clear();Assert.Empty(s.Rows);pending.SetResult(Review([Row()]));await load;Assert.False(s.Confirmed);}
    [Fact] public async Task FieldChangeDuringLookupCannotStartRead(){using var c=Company();using var s=new WellTestReviewState(c);var field=new TaskCompletionSource<string?>();var calls=0;var load=s.LoadAsync("well",()=>field.Task,_=>{calls++;return Task.FromResult(Review(new List<WellTestResponse>()));});s.Clear();field.SetResult("field");await load;Assert.Equal(0,calls);}
    [Fact] public async Task ChangedWellInvalidatesLateRead(){using var c=Company();using var s=new WellTestReviewState(c);var pending=new TaskCompletionSource<WellTestReview>();var load=s.LoadAsync("well",()=>Task.FromResult<string?>("field"),_=>pending.Task);s.Clear();pending.SetResult(Review([Row()]));await load;Assert.False(s.Confirmed);}
    [Fact] public async Task NoCompanyDoesNotRead(){using var c=new CompanyClientContext();using var s=new WellTestReviewState(c);await s.LoadAsync("well",()=>throw new Exception(),_=>throw new Exception());Assert.False(s.Confirmed);}
    [Fact] public async Task MissingFieldDoesNotRead(){using var c=Company();using var s=new WellTestReviewState(c);await Assert.ThrowsAsync<InvalidOperationException>(()=>s.LoadAsync("well",()=>Task.FromResult<string?>(null),_=>throw new Exception()));Assert.False(s.Confirmed);}
    [Theory][InlineData(WellTestCoverage.All,3)][InlineData(WellTestCoverage.Oil,1)][InlineData(WellTestCoverage.Gas,2)][InlineData(WellTestCoverage.Water,1)]
    public async Task EachCoverageCardOpensItsExactContributingRows(WellTestCoverage coverage,int count){using var c=Company();using var s=new WellTestReviewState(c);var a=Row();a.TestId="a";a.OilFlowAmount=0;var b=Row();b.TestId="b";b.GasFlowAmount=null;b.WaterFlowAmount=2;var d=Row();d.TestId="d";await s.LoadAsync("well",()=>Task.FromResult<string?>("field"),_=>Task.FromResult(Review(new List<WellTestResponse>{a,b,d})));s.SelectCoverage(coverage);Assert.Equal(count,s.Count(coverage));Assert.Equal(count,s.VisibleRows.Count);Assert.All(s.VisibleRows,x=>Assert.Contains(x,s.Rows));}
    [Fact] public async Task DetailCanOnlySelectVisibleRecordedIdentity(){using var c=Company();using var s=new WellTestReviewState(c);var row=Row();await s.LoadAsync("well",()=>Task.FromResult<string?>("field"),_=>Task.FromResult(Review(new List<WellTestResponse>{row})));s.SelectRecord(row.TestId);Assert.Same(row,s.Selected);s.SelectCoverage(WellTestCoverage.Oil);Assert.Null(s.Selected);s.SelectRecord(row.TestId);Assert.Null(s.Selected);s.SelectRecord("foreign-test");Assert.Null(s.Selected);}
    [Fact] public async Task CompanyChangeClearsCoverageAndDetail(){using var c=Company();using var s=new WellTestReviewState(c);await s.LoadAsync("well",()=>Task.FromResult<string?>("field"),_=>Task.FromResult(Review(new List<WellTestResponse>{Row()})));s.SelectCoverage(WellTestCoverage.Gas);s.SelectRecord("test/1");Assert.NotNull(s.Selected);c.Clear();Assert.Null(s.Selected);Assert.Equal(WellTestCoverage.All,s.Coverage);Assert.Empty(s.VisibleRows);}

    [Theory][InlineData("company")][InlineData("tenant")][InlineData("actor")][InlineData("field")][InlineData("well")][InlineData("retrieved")][InlineData("offset")][InlineData("nullreview")]
    public async Task WrongResponseProvenanceCannotPublish(string fault){using var c=Company();using var s=new WellTestReviewState(c);var review=Review([Row()]);review=fault switch{"company"=>review with{Company=new("tenant","other")},"tenant"=>review with{Company=new("other","A")},"actor"=>review with{Actor="other"},"field"=>review with{Field="other"},"well"=>review with{Well="other"},"retrieved"=>review with{RetrievedAtUtc=default},"offset"=>review with{RetrievedAtUtc=DateTimeOffset.UtcNow.ToOffset(TimeSpan.FromHours(3))},_=>null!};await Assert.ThrowsAsync<InvalidOperationException>(()=>s.LoadAsync("well",()=>Task.FromResult<string?>("field"),_=>Task.FromResult(review)));Assert.False(s.Confirmed);Assert.Null(s.RetrievedAtUtc);Assert.Empty(s.Rows);}

}
